/// Блоки, проводящие сигнал редстоуна.
///
/// Проводимость — своё свойство блока, и по виду его не угадать:
/// светокамень и блок редстоуна — полные кубы, но сигнал не проводят,
/// а слизь и корни мангра — проводят. Поэтому за основу взят полный
/// куб, а поверх — списки исключений с вики (страница Conductivity).
